import { FunctionComponent } from 'preact';
import { lazy, Suspense } from 'preact/compat';
import { useState } from 'preact/hooks';

import styles from './styles.module.scss';

const ConfirmationDialog = lazy(() => import('./ConfirmationDialog'));

interface Props {
  onClose: () => void,
  onDisable: (interval: 'day' | 'forever' ) => void
}

const Settings: FunctionComponent<Props> = ({ onClose, onDisable }: Props) => {
  const [selected, setSelected] = useState(null);

  const handleConfirmationDialogClose = (isApproved) => {
    setSelected(null);
    onDisable(isApproved ? selected : null);
  };

  return (
    <>
      <Suspense fallback={null}>
        <ConfirmationDialog open={!!selected} onClose={handleConfirmationDialogClose} />
      </Suspense>

      <div className={styles.overlay} onClick={onClose} />

      <div className={styles.popover}>
        <div className={styles.outerPopover}>
          <div className={styles.innerPopover}>
            <button className={styles.button} onClick={() => setSelected('day')}>Remove advertisements for a day</button>

            <button className={styles.button} onClick={() => setSelected('forever')}>Remove advertisements forever</button>

            <button onClick={onClose} className={styles.button}>Keep advertisments</button>
          </div>
        </div>
      </div>
    </>
  )
};

export default Settings;